{
  "mechanism_id": "directed_soft_code_affinity_transition_kl",
  "version": "3.0.0",
  "title": "Directed Soft Code-Affinity Transition KL",
  "equation": "For each valid pair b, let p_b = softmax_c(-||source_b - codebook_c||^2 / temperature) and q_b = softmax_c(-||target_b - codebook_c||^2 / temperature). The loss is weight * sum_b mask_b * sum_c p_bc * log((p_bc + epsilon) / (q_bc + epsilon)) / max(sum_b mask_b, 1).",
  "symbols": {
    "b": "Pair index in the batch.",
    "c": "Codebook-row index.",
    "source_b": "Source item residual for pair b, with shape [B, D].",
    "target_b": "Target item residual for pair b, with shape [B, D].",
    "codebook_c": "Codebook row c, with shape [C, D].",
    "mask_b": "Pair-validity weight; zero excludes a pair and one includes it.",
    "p_bc": "Soft assignment probability of source residual b to codebook row c.",
    "q_bc": "Soft assignment probability of target residual b to codebook row c.",
    "temperature": "Positive soft-assignment temperature.",
    "epsilon": "Positive numerical stabilizer inside the logarithm.",
    "weight": "External activation weight multiplying the masked mean loss.",
    "B": "Number of paired residuals.",
    "D": "Residual and codebook embedding dimension.",
    "C": "Number of codebook rows."
  },
  "parameters": {
    "temperature": 1.0,
    "epsilon": 1e-8
  },
  "target_paths": [
    "encoder",
    "codebook",
    "hard_sid_export"
  ],
  "hypotheses": [
    "The directed KL aligns source and target soft code affinities while allowing behavior-defined transitions to organize item residuals and codebook rows; it is a testable candidate for improving downstream recommendation quality, not a claim that ER improvement implies recommendation improvement.",
    "Select this mechanism only if matched-seed Stage-3 recall@10 improves over r8_control with an uncertainty interval excluding zero, while codebook occupancy does not collapse and the independent gradient and integration checks pass.",
    "The small activation weight is intended to limit assignment pressure; it does not guarantee occupancy preservation or downstream benefit."
  ],
  "expected_failure_modes": [
    "The term may improve soft assignment consistency without improving Stage-3 candidate retrieval or recall@10.",
    "The codebook may become less evenly occupied despite the low weight, producing concentrated hard SIDs or reduced code diversity.",
    "The temperature may make assignments too diffuse to affect hard SID export, or too sharp and induce excessive codebook pressure.",
    "A host gradient overwrite may discard the residual/encoder contribution; if the codebook gradient is also absent after host assembly, exported SIDs may remain identical to control.",
    "A directionally reversed implementation may pass basic finiteness checks but optimize the wrong transition relation."
  ],
  "tests": [
    {
      "id": "finite_forward",
      "kind": "numeric",
      "statement": "On the declared synthetic case, loss is finite and nonnegative; with all mask entries zero it is exactly zero."
    },
    {
      "id": "codebook_permutation",
      "kind": "metamorphic",
      "statement": "Permuting codebook rows leaves the scalar loss unchanged within tolerance."
    },
    {
      "id": "directionality",
      "kind": "metamorphic",
      "statement": "On a non-degenerate synthetic case, exchanging source and target changes the scalar loss beyond tolerance because KL(p||q) is directed."
    },
    {
      "id": "all_pairs_masked",
      "kind": "metamorphic",
      "statement": "Setting every mask entry to zero produces zero loss."
    },
    {
      "id": "declared_gradients",
      "kind": "gradient",
      "statement": "For the declared non-degenerate synthetic case, source, target, and codebook gradients are finite and nonzero before host gradient assembly."
    },
    {
      "id": "host_integration",
      "kind": "integration",
      "statement": "With the term enabled, verify separately that the codebook gradient after host assembly differs from control and that a matched export can change hard L1/L2/L3 SIDs; do not infer either from the pre-assembly gradient."
    },
    {
      "id": "downstream_selection",
      "kind": "integration",
      "statement": "Compare enabled and r8_control arms using matched seeds and Stage-3 recall@10; select only when the treatment-control uncertainty interval excludes zero in the favorable direction and occupancy does not collapse."
    }
  ],
  "judges": [
    "contract_audit",
    "forward_oracle",
    "derivative_evidence",
    "property_checks",
    "integration_on_off"
  ],
  "forbidden_substitutions": [
    {
      "id": "symmetric_or_reverse_kl",
      "pattern": "((KL\\s*\\(\\s*p\\s*\\|\\|\\s*q\\s*\\)\\s*\\+\\s*KL\\s*\\(\\s*q\\s*\\|\\|\\s*p\\s*\\))|KL\\s*\\(\\s*q\\s*\\|\\|\\s*p\\s*\\))",
      "reason": "Replacing the directed source-to-target KL with a symmetric or reverse KL changes the transition mechanism and its declared swap behavior."
    },
    {
      "id": "detached_assignments",
      "pattern": "(detach\\s*\\(\\s*(p|q|source|target|codebook)\\s*\\)|stop_gradient\\s*\\(\\s*(p|q|source|target|codebook)\\s*\\))",
      "reason": "Detaching assignments or inputs can block the declared gradients to residuals or codebook."
    },
    {
      "id": "encoder_only_surrogate",
      "pattern": "(codebook\\s*\\.\\s*grad\\s*=\\s*None|codebook\\s*=\\s*codebook\\s*\\.\\s*detach\\s*\\(\\s*\\))",
      "reason": "The host overwrites encoder gradients; an encoder-only term would be discarded and cannot reliably move exported codes."
    },
    {
      "id": "hard_assignment_replacement",
      "pattern": "(argmin\\s*\\(|one_hot\\s*\\([^\\n]*(assignment|assignments))",
      "reason": "Replacing the specified soft affinities with hard assignments changes the objective and may create abrupt codebook pressure or block useful gradients."
    }
  ],
  "invariants": [
    {
      "id": "permute_codebook",
      "transform": "permute_codebook",
      "expect": "unchanged",
      "tolerance": 1e-6
    },
    {
      "id": "swap_source_target",
      "transform": "swap_source_target",
      "expect": "changed",
      "tolerance": 1e-6
    },
    {
      "id": "mask_all",
      "transform": "mask_all",
      "expect": "zero",
      "tolerance": 0.0
    }
  ],
  "gradient_targets": {
    "source": "nonzero",
    "target": "nonzero",
    "codebook": "nonzero"
  },
  "inputs": {
    "source": {
      "shape": [
        8,
        4
      ],
      "seed": 11
    },
    "target": {
      "shape": [
        8,
        4
      ],
      "seed": 12
    },
    "codebook": {
      "shape": [
        6,
        4
      ],
      "seed": 13
    },
    "mask": {
      "seed": 17,
      "valid_fraction": 0.75
    }
  },
  "activation": {
    "kind": "term",
    "weight": 0.001
  },
  "differentiation": {
    "occupancy_preservation": "No explicit occupancy constraint is included. The low activation weight limits intended pressure but does not ensure balanced hard-code usage; measure per-level occupancy, entropy, and Gini, and reject the arm if occupancy collapses.",
    "vs_r8": [
      {
        "lane": "r8_01_directed_l1_transition_nce",
        "why": "Uses contrastive directed L1 code-transition classification; this mechanism instead matches continuous soft affinities to learned codebook rows with a directed KL."
      },
      {
        "lane": "r8_02_l1_next_item_prediction",
        "why": "Predicts next-item semantics at L1; this mechanism compares source and target residual-to-codebook affinity distributions."
      },
      {
        "lane": "r8_03_successor_profile_js",
        "why": "Co-clusters successor profiles using JS divergence; this mechanism uses paired residual geometry and asymmetric KL, not successor-profile distributions."
      },
      {
        "lane": "r8_04_behavior_conditioned_ot",
        "why": "Uses entropic optimal transport as a behavior-conditioned quantizer; this mechanism leaves quantization assignment to the host and adds a directed pairwise affinity loss."
      },
      {
        "lane": "r8_05_three_level_distillation",
        "why": "Distills a teacher into three code levels; this mechanism has no teacher and applies to the supplied residual/codebook pair."
      },
      {
        "lane": "r8_06_train_graph_diffusion",
        "why": "Preserves train-graph diffusion distances; this mechanism uses per-pair source-to-target code affinities rather than graph diffusion."
      },
      {
        "lane": "r8_07_hyperbolic_gyro",
        "why": "Uses hyperbolic gyro-translation; this mechanism uses Euclidean squared distances and a categorical affinity KL."
      },
      {
        "lane": "r8_08_hyperbolic_frechet",
        "why": "Uses hyperbolic Frechet successor barycentres; this mechanism forms no barycentres and compares soft code affinities."
      },
      {
        "lane": "r8_09_hyperbolic_branching",
        "why": "Organizes a hyperbolic radial hierarchy; this mechanism imposes no radial or hierarchical geometry."
      },
      {
        "lane": "r8_10_hyperbolic_gw",
        "why": "Uses graph-code Gromov-Wasserstein alignment; this mechanism has no graph coupling or transport solve."
      },
      {
        "lane": "r8_control",
        "why": "The control has no auxiliary behavior-aware term; this mechanism adds a directed, codebook-differentiable pairwise affinity objective and must earn selection by downstream evaluation."
      }
    ],
    "vs_reference_arm": "Unlike the gentle codebook-reaching geometry-transport reference arm, this mechanism does not transport pairwise residual geometry or optimize an ER proxy; it matches source and target soft affinities to the same learned codebook with an explicitly directed KL. It may still fail to improve downstream quality and is subject to the same occupancy and matched Stage-3 checks."
  },
  "provenance": {
    "authored_by": "researcher",
    "authored_at": "2026-10-21T00:00:00Z"
  }
}
